<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/bootstrap.php';
require_user();
header('Cache-Control: no-store, private');
$uid = current_user_id();
$db = database_connection();
$leadStmt = $db->prepare('SELECT l.id, l.name, l.interest, l.message, l.status, l.created_at, e.name AS expert_name FROM leads l LEFT JOIN experts e ON e.id = l.expert_id WHERE l.user_id = :uid ORDER BY l.created_at DESC');
$leadStmt->execute(['uid' => $uid]);
$leads = $leadStmt->fetchAll();
$db->prepare("UPDATE lead_messages m INNER JOIN leads l ON l.id = m.lead_id SET m.is_read = 1 WHERE l.user_id = :uid AND m.sender_type = 'admin'")->execute(['uid' => $uid]);
$bookingStmt = $db->prepare('SELECT b.id, b.interest, b.preferred_at, b.status, e.name AS expert_name FROM bookings b LEFT JOIN experts e ON e.id = b.expert_id WHERE b.user_id = :uid ORDER BY b.preferred_at DESC');
$bookingStmt->execute(['uid' => $uid]);
$bookings = $bookingStmt->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex, nofollow"><title>My guidance · You Aspirant</title><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="features.css"></head><body class="feature-page"><header class="feature-header"><a class="brand" href="/"><span class="brand-mark"><span>Y</span></span><span class="brand-copy"><strong>you aspirant</strong><small>Your student space</small></span></a><form method="post" action="account-logout"><input type="hidden" name="csrf_token" value="<?= escape_html(csrf_token()) ?>"><button class="text-link" type="submit">Sign out ↗</button></form></header><main class="feature-shell"><p class="eyebrow eyebrow-muted">A steady place to keep track</p><h1>Hello, <?= escape_html($_SESSION['user_name'] ?? 'there') ?>.</h1><p>Read replies from your guidance team and see who is supporting you.</p><p id="student-notification" class="feature-success" role="status" hidden></p><div class="feature-actions"><a class="button button-dark" href="/#contact">Send a new enquiry ↗</a><a class="button button-outline" href="book">Request a counselling slot ↗</a></div><h2 class="feature-section-title">Your enquiries</h2><?php if (!$leads): ?><div class="content-empty"><p>Your enquiries and expert replies will show up here. <a href="/#contact">Start with a question ↗</a></p></div><?php endif; ?><?php foreach ($leads as $lead): ?><section id="lead-<?= (int) $lead['id'] ?>" class="feature-panel conversation-card"><div class="conversation-head"><div><span class="status-pill status-<?= escape_html($lead['status']) ?>"><?= escape_html($lead['status']) ?></span><h2><?= escape_html($lead['interest']) ?></h2><small>Sent <?= escape_html(date('M j, Y', strtotime((string) $lead['created_at']))) ?> · <?= $lead['expert_name'] ? 'Your expert: ' . escape_html($lead['expert_name']) : 'An expert will be assigned by the team' ?></small></div></div><?php if (trim((string) $lead['message']) !== ''): ?><p class="original-message"><?= nl2br(escape_html($lead['message'])) ?></p><?php endif; ?><?php $messages = $db->prepare('SELECT sender_type, body, created_at FROM lead_messages WHERE lead_id = :lead ORDER BY created_at ASC, id ASC'); $messages->execute(['lead' => $lead['id']]); foreach ($messages->fetchAll() as $message): ?><article class="chat-message chat-<?= escape_html($message['sender_type']) ?>"><strong><?= $message['sender_type'] === 'admin' ? 'You Aspirant team' : 'You' ?></strong><p><?= nl2br(escape_html($message['body'])) ?></p><small><?= escape_html(date('M j, g:i a', strtotime((string) $message['created_at']))) ?></small></article><?php endforeach; ?><form class="reply-form" method="post" action="student-action"><input type="hidden" name="csrf_token" value="<?= escape_html(csrf_token()) ?>"><input type="hidden" name="lead_id" value="<?= (int) $lead['id'] ?>"><label for="reply-<?= (int) $lead['id'] ?>">Reply to your guidance team<textarea id="reply-<?= (int) $lead['id'] ?>" name="body" maxlength="3000" required></textarea></label><button class="button button-dark" type="submit">Send reply ↗</button></form></section><?php endforeach; ?><h2 class="feature-section-title">Counselling requests</h2><?php if (!$bookings): ?><p class="feature-muted">No counselling slots requested yet.</p><?php endif; ?><div class="booking-list"><?php foreach ($bookings as $booking): ?><article class="booking-row"><div><strong><?= escape_html($booking['interest']) ?></strong><small><?= escape_html(date('M j, Y · g:i a', strtotime((string) $booking['preferred_at']))) ?><?= $booking['expert_name'] ? ' · ' . escape_html($booking['expert_name']) : '' ?></small></div><span class="status-pill status-<?= escape_html($booking['status']) ?>"><?= escape_html($booking['status']) ?></span></article><?php endforeach; ?></div></main><script>(function(){const n=document.querySelector("#student-notification");async function check(){try{const r=await fetch("student-notifications",{credentials:"same-origin",cache:"no-store"});if(!r.ok)return;const d=await r.json();if(d.unread>0){n.hidden=false;n.textContent="You have a new reply from your guidance team. Refresh this page to read it.";}}catch(_){}}check();window.setInterval(check,15000);})();</script></body></html>
